#define main original_cli_main
#include "../dxtc2-cuda/main.cu"
#undef main
#include <fstream>
#include <iomanip>
#include <string>
#include <vector>
#define CK(x) do{auto err=(x);if(err!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(err));exit(3);}}while(0)
const uint GUARD=0xdeadbeef;
double mse(const std::vector<uint>&out,const std::vector<uint>&im,int b){uint word=out[2*b],codes=out[2*b+1],a=word&65535,c=word>>16;int p[4][3];auto rgb=[](uint w,int*x){int r=(w>>11)&31,g=(w>>5)&63,b=w&31;x[0]=(r<<3)|(r>>2);x[1]=(g<<2)|(g>>4);x[2]=(b<<3)|(b>>2);};rgb(a,p[0]);rgb(c,p[1]);for(int k=0;k<3;k++){p[2][k]=a>c?(2*p[0][k]+p[1][k])/3:(p[0][k]+p[1][k])/2;p[3][k]=a>c?(p[0][k]+2*p[1][k])/3:0;}int err=0;for(int j=0;j<16;j++)for(int k=0;k<3;k++){int d=p[(codes>>(2*j))&3][k]-int((im[b*16+j]>>(8*k))&255);err+=d*d;}return double(err)/48;}
int main(){std::string root=std::string(__FILE__).substr(0,std::string(__FILE__).find_last_of('/'));std::ifstream f(root+"/fixture.bin",std::ios::binary|std::ios::ate);size_t sz=f.tellg();f.seekg(0);std::vector<uint>fixture(sz/4);f.read((char*)fixture.data(),sz);std::vector<uint>perms(fixture.begin()+5,fixture.begin()+1029),im(fixture.begin()+1029,fixture.end());uint expected[1024];computePermutations(expected);if(!std::equal(perms.begin(),perms.end(),expected))return 4;int nb=12;
 std::vector<uint>pw(1040,GUARD),iw(208,GUARD),rw(40,GUARD);std::copy(perms.begin(),perms.end(),pw.begin()+8);std::copy(im.begin(),im.end(),iw.begin()+8);uint *dp,*di,*dr;CK(cudaMalloc(&dp,pw.size()*4));CK(cudaMalloc(&di,iw.size()*4));CK(cudaMalloc(&dr,rw.size()*4));CK(cudaMemcpy(dp,pw.data(),pw.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(di,iw.data(),iw.size()*4,cudaMemcpyHostToDevice));for(auto pair:{std::pair<int,int>(12,0),{5,2}}){compress<<<pair.first,64>>>(dp+8,di+8,(uint2*)(dr+8),pair.second);CK(cudaDeviceSynchronize());}
 for(int trial=1;trial<=5;trial++){std::vector<uint>out;std::vector<double>times;bool ok=true;double elapsed=0,mq=0;int pi=0;for(auto pair:{std::pair<int,int>(12,0),{5,2}}){int n=pair.first,off=pair.second;std::fill(rw.begin(),rw.end(),GUARD);CK(cudaMemcpy(dr,rw.data(),rw.size()*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int r=0;r<10;r++)compress<<<n,64>>>(dp+8,di+8,(uint2*)(dr+8),off);CK(cudaDeviceSynchronize());double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;elapsed+=t;times.push_back(t);
 std::vector<uint>p(pw.size()),i(iw.size()),r(rw.size());CK(cudaMemcpy(p.data(),dp,p.size()*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(i.data(),di,i.size()*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(r.data(),dr,r.size()*4,cudaMemcpyDeviceToHost));ok &= p==pw&&i==iw;for(int k=0;k<8;k++)ok &= r[k]==GUARD&&r[r.size()-1-k]==GUARD;std::vector<uint>payload(r.begin()+8,r.end()-8);for(int b=0;b<nb;b++){if(b>=off&&b<off+n){double q=mse(payload,im,b);mq=std::max(mq,q);ok &= std::isfinite(q)&&q<=256;}else ok &= payload[2*b]==GUARD&&payload[2*b+1]==GUARD;}
 if(pi++==0){out.insert(out.end(),fixture.begin(),fixture.begin()+5);out.insert(out.end(),p.begin()+8,p.end()-8);out.insert(out.end(),i.begin()+8,i.end()-8);}out.insert(out.end(),r.begin(),r.end());out.insert(out.end(),p.begin(),p.end());out.insert(out.end(),i.begin(),i.end());}
 std::string name="output_trial"+std::to_string(trial)+".bin";std::ofstream o(name,std::ios::binary);o.write((char*)out.data(),out.size()*4);o.close();std::cout<<std::setprecision(17)<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<elapsed<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<out.size()<<",\"max_abs_error\":0,\"max_rel_error\":0,\"max_fixture_RGB_MSE\":"<<mq<<",\"path_times_seconds\":["<<times[0]<<","<<times[1]<<"],\"timing_region\":\"sum2_hostinclusive_10kernel_batches_div10\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\""<<name<<"\",\"dtype\":\"uint32\",\"count\":"<<out.size()<<",\"byte_order\":\"little\"}}\n";
 }
